useEffect(() => {
    try {
      const stored = localStorage.getItem('cova_quiz_answers')
      if (stored) {
        const answers = JSON.parse(stored)
        const computed = computeDimensions(answers)
        setDimensions(computed)
      } else {
        // Fallback: default Quiet Naturalist profile
        setDimensions({ warmth: 60, complexity: 30, organic: 80, layered: 45, heritage: 50, character: 55 })
      }
    } catch (e) {
      console.error('Failed to load quiz answers', e)
      setDimensions({ warmth: 60, complexity: 30, organic: 80, layered: 45, heritage: 50, character: 55 })
    }
  }, [])

